interface UsersView {                       // View is passive
    fun showLoading()
    fun hideLoading()
    fun showUsers(users: List<User>)
    fun showError(message: String)
    fun showEmptyState()
}

class UsersPresenter(private val repo: UserRepository) {
    private var view: UsersView? = null     // manual reference management!

    fun attach(view: UsersView) { this.view = view }
    fun detach() { this.view = null }       // forget it → memory leak

    fun loadUsers(query: String) {
        view?.showLoading()
        scope.launch {
            try {
                val users = repo.getUsers(query)
                view?.hideLoading()
                if (users.isEmpty()) view?.showEmptyState()
                else view?.showUsers(users)
            } catch (e: Exception) {
                view?.hideLoading()
                view?.showError(e.message.orEmpty())
            }
        }
    }
}

